// 기존 Obsidian Vault (Google Drive) 폴더 ID 매핑
// 현우님의 실제 Vault 구조에 통합

const VAULT_DRIVE_ROOT = '1REfIN5HYZEAedSjlL3hn8DryPDOvrUx6';

// VPS 폴더 → Google Drive 폴더 ID
const FOLDER_MAP = {
  '00-MOC':        '1REfIN5HYZEAedSjlL3hn8DryPDOvrUx6',  // Vault Root
  '01-Concepts':   '1ogBK1ZmjXG4HhB9nk6BKCBPLg8YxGdLW',  // 100. Research
  '02-Entities':   '1ntnTT3BOd7Wp_p3VBXOuxtdI9aYsLpjo',  // 200. Sectors (default, GICS override below)
  '03-Notes':      '1t7fLsr0WUsNOSBoM_6QaMgTwsqDHOyaE',  // 00. Inbox
  '04-Daily':      '12XGamKfK4QyR9heimtUK1I2GF-GfKM4g',  // 10. Daily Notes/11. Daily
  '05-Weekly':     '1eGFZXjMv6N5nmeMHJoAGoryLpw5TJAVk',  // 10. Daily Notes/12. Weekly
  '06-Projects':   '1REfIN5HYZEAedSjlL3hn8DryPDOvrUx6',  // Vault Root
  '07-Reference':  '1ogBK1ZmjXG4HhB9nk6BKCBPLg8YxGdLW',  // 100. Research
  'templates':     '1zvWXM2XQjsXEFsdFV5gyA3-bXF_NhKif'   // 90. Template
};

// GICS Sector → Vault 200. Sectors/ 하위 폴더 ID
const GICS_SECTOR_MAP = {
  '10': '1v5eMJPagQ2VYlZg_PxuDwNUPMy3LC1B1',  // 210. Energy
  '15': '1JEoebgyPHH6m7kmjX5TJ3NejQzW0LUb9',  // 225. Materials
  '20': '1-ZTweJTKAe5AKlZ5Wew4HrpYEkWCEu7r',  // 220. Industrials
  '25': '1WPTNaRypzuO0-O9DUiohyq9esu5vIzcE',  // 230. Consumer
  '30': '1WPTNaRypzuO0-O9DUiohyq9esu5vIzcE',  // 230. Consumer (combined)
  '35': '1w0XlYF3Tofweq8yjUeR9MNtVSxe8TuYN',  // 240. Health Care
  '40': '10NY5kzNLAL4yUJn5sax8jxeEGL2hiGaD',  // 250. Financials
  '45': '1GyRpbJyen4_L1w_nc76aJEJxNaVYZe4Y',  // 260. Information Technology
  '50': '1vzFxGefRHd0B3PxDZZjct5G1ZjyX8m1e',  // 270. Communication Services
  '55': '1iAKe2nN-l3eW9FSAc_le9fLVD21wKo65',  // 280. Utilities
  '60': '1IRYmYC9R5xAxzQ6CSJmvGQY4mbo0Twh3'   // 290. Real Estate
};

// IT Industry Group → 세부 폴더
const IT_SUBGROUP_MAP = {
  '4510': '1lrPmI1EOPm99rzSCRRK-zEj3I8L_Xelx',  // 261. Software & Services
  '4520': '1xLpVK-BY1ACGwerdmcdymiDaeR4YokL3',  // 262. Technology Hardware
  '4530': '1ZBjGdlgyGEy1q72MEBx_pl5_4oLSb-QV'   // 263. Semiconductors
};

return [{
  json: {
    vaultDriveRoot: VAULT_DRIVE_ROOT,
    folderMap: FOLDER_MAP,
    gicsSectorMap: GICS_SECTOR_MAP,
    itSubgroupMap: IT_SUBGROUP_MAP,
    knowledgePath: '/home/openclaw/.openclaw/workspace/knowledge',
    timestamp: new Date().toISOString()
  }
}];

// SSH 결과를 파싱하여 파일별 아이템 생성
const config = $('Vault → Drive 매핑 설정').first().json;
const stdout = $('변경 파일 감지 (SSH)').first().json.stdout || '';
const allFiles = stdout.split('\n').filter(f => f.trim() && f.endsWith('.md'));

if (allFiles.length === 0) {
  return [{ json: { status: 'no_changes', message: '변경된 파일 없음', count: 0 } }];
}

// 각 파일을 개별 아이템으로 반환
return allFiles.map(filePath => {
  const topFolder = filePath.split('/')[0];
  const targetFolderId = config.folderMap[topFolder] || config.vaultDriveRoot;

  return {
    json: {
      filePath,
      topFolder,
      fileName: filePath.split('/').pop(),
      fullPath: `${config.knowledgePath}/${filePath}`,
      targetFolderId,
      isEntity: topFolder === '02-Entities',
      gicsSectorMap: config.gicsSectorMap,
      itSubgroupMap: config.itSubgroupMap,
      vaultDriveRoot: config.vaultDriveRoot
    }
  };
});

// SSH로 읽은 텍스트를 바이너리(MD 파일)로 변환
// + Entity 파일은 GICS frontmatter 파싱하여 정확한 섹터 폴더로 라우팅

const fileData = $('파일 목록 파싱').item.json;
const content = $input.first().json.stdout || '';
const fileName = fileData.fileName;
let targetFolderId = fileData.targetFolderId;

// Entity 파일이면 GICS 태그에서 섹터 폴더 결정
if (fileData.isEntity && content.includes('gics:')) {
  const gicsSectorMap = fileData.gicsSectorMap || {};
  const itSubgroupMap = fileData.itSubgroupMap || {};

  // frontmatter에서 GICS sector 코드 추출
  // 패턴: #GICS/45/4530 또는 gics: sector: "45 - ..."
  const gicsTagMatch = content.match(/#GICS\/(\d{2})(?:\/(\d{4}))?/);
  const gicsSectorMatch = content.match(/sector:\s*["']?(\d{2})/);

  const sectorCode = gicsTagMatch ? gicsTagMatch[1] : (gicsSectorMatch ? gicsSectorMatch[1] : null);
  const igCode = gicsTagMatch ? gicsTagMatch[2] : null;

  if (sectorCode) {
    // IT 섹터(45)이고 Industry Group이 있으면 세부 폴더
    if (sectorCode === '45' && igCode && itSubgroupMap[igCode]) {
      targetFolderId = itSubgroupMap[igCode];
    } else if (gicsSectorMap[sectorCode]) {
      targetFolderId = gicsSectorMap[sectorCode];
    }
  }
}

const base64Content = Buffer.from(content, 'utf-8').toString('base64');

return {
  json: {
    ...fileData,
    targetFolderId,
    contentLength: content.length
  },
  binary: {
    data: {
      data: base64Content,
      mimeType: 'text/markdown',
      fileName: fileName
    }
  }
};

// 동기화 리포트 생성
const items = $input.all();
const syncedCount = items.length;
const now = new Date().toLocaleString('ko-KR', {timeZone: 'Asia/Seoul'});

const fileList = items.map(item => {
  const name = item.json.fileName || item.json.name || 'unknown';
  const folder = item.json.topFolder || '';
  return `  ${folder}/${name}`;
}).join('\n');

const report = [
  '\ud83d\udcc1 OpenClaw Knowledge Sync',
  '\u2501'.repeat(24),
  `\u23f0 ${now}`,
  `\ud83d\udcc4 ${syncedCount}\uac74 \ub3d9\uae30\ud654 \uc644\ub8cc`,
  '',
  fileList,
  '',
  '\u2705 Google Drive Vault \uc5c5\ub85c\ub4dc \uc644\ub8cc'
].join('\n');

return [{ json: { report, syncedCount, timestamp: now } }];
